WITH with_windows AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, ROW_NUMBER() OVER w_grp AS row_seq, RANK() OVER w_running AS discount_pct_rank, FIRST_VALUE(channel, TRUE) OVER (PARTITION BY channel, promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel, LAG(discount_pct, 2, 0) OVER w_running_2 AS prev_discount_pct, ROW_NUMBER() OVER (PARTITION BY promo_code, channel ORDER BY discount_pct DESC, id) AS seq_no FROM promotions WINDOW w_grp AS (PARTITION BY channel ORDER BY starts_on DESC, id), w_running AS (ORDER BY discount_pct), w_running_2 AS (PARTITION BY promo_code ORDER BY starts_on, id)), scored AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, row_seq, discount_pct_rank, first_known_channel, prev_discount_pct, seq_no, LAST_VALUE(channel) IGNORE NULLS OVER w_grp AS last_known_channel, LAST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY promo_code, channel ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel_2 FROM with_windows WINDOW w_grp AS (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), remaining_keys AS (SELECT promo_code, channel FROM scored INTERSECT SELECT promo_code, channel FROM promotions WHERE starts_on < '2023-11-01'), verified AS (SELECT s.* FROM scored s INNER JOIN remaining_keys k ON s.promo_code = k.promo_code AND s.channel = k.channel) SELECT *, RANK() OVER (ORDER BY discount_pct_rank DESC NULLS FIRST) AS discount_pct_rank_rank, RANK() OVER (ORDER BY discount_pct DESC) AS discount_pct_rank_2, CUME_DIST() OVER (PARTITION BY promo_code, channel ORDER BY seq_no DESC NULLS LAST) AS seq_no_cume_dist FROM verified;
